import * as THREE from './vendor/three.module.js';
const $=s=>document.querySelector(s);const defaults={finish:'oak',frame:'chalk',width:140,depth:70,tray:false,shelf:false};let state={...defaults},inches=false,auto=false;const finishes={oak:{name:'Natural oak',base:'#c8a06e',grain:'#89663e',extra:0},walnut:{name:'Smoked walnut',base:'#79533a',grain:'#392719',extra:70},ash:{name:'Pale ash',base:'#dfd0af',grain:'#aa9470',extra:35},black:{name:'Charcoal',base:'#373b35',grain:'#20241f',extra:45}};const frameName=()=>state.frame==='chalk'?'Chalk':'Graphite';const price=()=>Math.round(429+(state.width-140)*1.7+(state.depth-70)*2.2+finishes[state.finish].extra+(state.tray?35:0)+(state.shelf?65:0));const measure=n=>inches?`${(n/2.54).toFixed(1)} in`:`${n} cm`;let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
let scene,camera,renderer,desk,wood,metal,observer;let azimuth=.78,elevation=.38,distance=3.4;const canvas=$('#scene');
function texture(f){const c=document.createElement('canvas');c.width=1024;c.height=256;const x=c.getContext('2d');x.fillStyle=f.base;x.fillRect(0,0,1024,256);let seed=113;const rand=()=>{seed=(seed*16807)%2147483647;return(seed-1)/2147483646};for(let i=0;i<430;i++){x.strokeStyle=f.grain;x.globalAlpha=.025+rand()*.13;x.lineWidth=.3+rand()*1.2;x.beginPath();let y=rand()*256;for(let a=0;a<=1024;a+=16){let b=y+Math.sin(a/130+i)*(.5+rand()*2);a?x.lineTo(a,b):x.moveTo(a,b)}x.stroke()}const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;t.anisotropy=renderer.capabilities.getMaxAnisotropy();return t}
function box(w,h,d,x,y,z,mat){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;desk.add(m);return m}
function rebuild(){if(!renderer)return;while(desk.children.length){const o=desk.children[0];o.geometry.dispose();desk.remove(o)}if(wood){wood.map.dispose();wood.dispose();metal.dispose()}wood=new THREE.MeshStandardMaterial({map:texture(finishes[state.finish]),roughness:.65});metal=new THREE.MeshStandardMaterial({color:state.frame==='chalk'?0xe8e6d9:0x353d37,roughness:.65});const w=state.width/100,d=state.depth/100;box(w,.045,d,0,.7275,0,wood);for(const x of[-w/2+.10,w/2-.10]){for(const z of[-d/2+.08,d/2-.08])box(.045,.70,.045,x,.35,z,metal);box(.045,.05,d-.12,x,.67,0,metal)}box(w-.2,.055,.035,0,.655,-d/2+.08,metal);if(state.tray){box(w*.65,.025,.16,0,.59,-d/2+.12,metal);box(w*.65,.065,.018,0,.62,-d/2+.2,metal)}if(state.shelf){const sw=Math.min(.85,w-.25);box(sw,.035,.22,0,.87,-d/2+.16,wood);for(const x of[-sw/2+.07,sw/2-.07])box(.025,.12,.16,x,.79,-d/2+.16,metal)} }
function updateCamera(){if(!camera)return;const fit=distance*Math.max(1,.95/camera.aspect);camera.position.set(Math.sin(azimuth)*Math.cos(elevation)*fit,.35+Math.sin(elevation)*fit,Math.cos(azimuth)*Math.cos(elevation)*fit);camera.lookAt(0,.4,0)}
try{renderer=new THREE.WebGLRenderer({canvas,antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.setClearColor(0xeceee7);renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.2;scene=new THREE.Scene();scene.fog=new THREE.Fog(0xeceee7,7,13);camera=new THREE.PerspectiveCamera(34,1,.1,30);desk=new THREE.Group();scene.add(desk);scene.add(new THREE.HemisphereLight(0xffffff,0xc1c6ae,2.8));const light=new THREE.DirectionalLight(0xfff5e7,4);light.position.set(-2,5,3);light.castShadow=true;light.shadow.mapSize.set(2048,2048);light.shadow.camera.left=-3;light.shadow.camera.right=3;light.shadow.camera.top=3;light.shadow.camera.bottom=-3;light.shadow.normalBias=.025;light.shadow.radius=5;scene.add(light);const floor=new THREE.Mesh(new THREE.PlaneGeometry(200,200),new THREE.MeshStandardMaterial({color:0xeceee7,roughness:1}));floor.rotation.x=-Math.PI/2;floor.position.y=-.005;floor.receiveShadow=true;scene.add(floor);observer=new ResizeObserver(()=>{const r=canvas.parentElement.getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();updateCamera()});observer.observe(canvas.parentElement);let last=0;function animate(t){requestAnimationFrame(animate);if(auto&&(!document.hidden)){azimuth+=Math.min((t-last)/1000,.05)*.18;updateCamera()}last=t;renderer.render(scene,camera)}updateCamera();requestAnimationFrame(animate)}catch(e){renderer=null;$('#webgl-error').hidden=false;$('#snapshot').disabled=true;$('#rotate').disabled=true;$('#reset-view').disabled=true}
let dragging=false,px=0,py=0;canvas.addEventListener('pointerdown',e=>{dragging=true;px=e.clientX;py=e.clientY;canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!dragging)return;azimuth-=(e.clientX-px)*.008;elevation=Math.max(.07,Math.min(1.2,elevation+(e.clientY-py)*.006));px=e.clientX;py=e.clientY;updateCamera()});for(const ev of['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(ev,()=>dragging=false);canvas.addEventListener('wheel',e=>{e.preventDefault();distance=Math.max(2.1,Math.min(5,distance+e.deltaY*.002));updateCamera()},{passive:false});$('#rotate').onclick=()=>{auto=!auto;$('#rotate').setAttribute('aria-pressed',String(auto));$('#rotate').textContent=auto?'Ⅱ Pause rotation':'↻ Auto rotate'};$('#reset-view').onclick=()=>{azimuth=.78;elevation=.38;distance=3.4;updateCamera()};
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}$('#snapshot').onclick=()=>{renderer.render(scene,camera);canvas.toBlob(b=>{if(b)download(b,'formdesk-design.png','image/png')},'image/png')};
function update(){for(const key of['width','depth']){$('#'+key).value=state[key];$('#'+key+'-value').textContent=measure(state[key])}$('#min-width').textContent=measure(100);$('#max-width').textContent=measure(200);$('#min-depth').textContent=measure(50);$('#max-depth').textContent=measure(90);$('#height-value').textContent=measure(75);$('#units').textContent=inches?'in → cm':'cm → in';$('#finish-label').textContent=finishes[state.finish].name;$('#material-caption').textContent=`${finishes[state.finish].name} / ${frameName()} frame`;$('#price').innerHTML=`$${price().toLocaleString('en-US')}<span> USD</span>`;document.querySelectorAll('[data-finish]').forEach(b=>{const s=b.dataset.finish===state.finish;b.classList.toggle('selected',s);b.setAttribute('aria-pressed',String(s))});document.querySelectorAll('[data-frame]').forEach(b=>{const s=b.dataset.frame===state.frame;b.classList.toggle('selected',s);b.setAttribute('aria-pressed',String(s))});for(const k of['tray','shelf'])$('#'+k).checked=state[k];rebuild()}
document.querySelectorAll('[data-finish]').forEach(b=>b.onclick=()=>{state.finish=b.dataset.finish;update()});document.querySelectorAll('[data-frame]').forEach(b=>b.onclick=()=>{state.frame=b.dataset.frame;update()});for(const k of['width','depth'])$('#'+k).oninput=e=>{state[k]=Number(e.target.value);update()};for(const k of['tray','shelf'])$('#'+k).onchange=e=>{state[k]=e.target.checked;update()};$('#units').onclick=()=>{inches=!inches;update()};$('#reset').onclick=()=>{state={...defaults};update();toast('Design reset to the original')};
function valid(s){return s&&Object.hasOwn(finishes,s.finish)&&['chalk','graphite'].includes(s.frame)&&Number.isInteger(s.width)&&s.width>=100&&s.width<=200&&s.width%10===0&&Number.isInteger(s.depth)&&s.depth>=50&&s.depth<=90&&s.depth%5===0&&typeof s.tray==='boolean'&&typeof s.shelf==='boolean'}
$('#save').onclick=()=>{try{localStorage.setItem('formdesk-design',JSON.stringify(state));toast('Design saved in this browser')}catch{toast('Your browser could not save this design')}};$('#saved').onclick=()=>{try{const saved=JSON.parse(localStorage.getItem('formdesk-design'));if(!valid(saved)){toast('No saved design yet. Configure your desk and select Save.');return}state={...defaults,...saved};update();toast('Your saved design is restored')}catch{toast('Saved design could not be restored')}};
$('#quote').onclick=()=>{$('#summary').textContent=`Everyday Desk · ${state.width} × ${state.depth} × 75 cm · ${finishes[state.finish].name} · ${frameName()} frame${state.tray?' · Cable tray':''}${state.shelf?' · Monitor shelf':''} · Estimated $${price()} USD`;$('#quote-dialog').showModal()};$('#close-dialog').onclick=()=>$('#quote-dialog').close();$('#quote-dialog').addEventListener('click',e=>{if(e.target===$('#quote-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});$('#quote-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const text=`FORMDESK — DESIGN & QUOTE BRIEF\nCreated: ${new Date().toISOString().slice(0,10)}\n\nCustomer: ${f.get('name')}\nEmail: ${f.get('email')}\n\nProduct: Everyday Desk\nDimensions: ${state.width} cm W × ${state.depth} cm D × 75 cm H\nSurface: ${finishes[state.finish].name}\nFrame: ${frameName()}\nCable tray: ${state.tray?'Yes':'No'}\nMonitor shelf: ${state.shelf?'Yes':'No'}\n\nILLUSTRATIVE ESTIMATE: $${price()} USD\nShipping and taxes excluded. Final specifications, availability and price require confirmation by your furniture maker. This is a concept demo, not a binding quotation or order.\n\nProject notes:\n${f.get('notes')||'None'}\n\nThis brief was downloaded locally. No request has been sent.\n`;download(text,'formdesk-quote-brief.txt','text/plain;charset=utf-8');$('#quote-dialog').close();toast('Brief downloaded. Share it with your furniture maker.')};update();
